private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel) {
    // Find the bucket with label minLabel
    Set<Integer> bucket = null;
    for (Set<Integer> b : bucketsByLabel) {
        if (b.contains(minLabel)) {
            bucket = b;
            break;
        }
    }

    // Move all vertices from the bucket with label minLabel to the bucket with label 0
    Set<Integer> bucket0 = bucketsByLabel.get(0);
    bucket0.addAll(bucket);

    // Clear the bucket with label minLabel
    bucket.clear();

    // Update the labeling
    labels.set(minLabel, 0);
}

void reload(ArrayList<HashSet<Integer>> bucketsByLabel,ArrayList<Integer> labels,int minLabel) {
    int i = minLabel;
    while (i > 0) {
        HashSet<Integer> set = bucketsByLabel.get(i);
        if (set.contains(i)) {
            set.remove(i);
